import time

def unit_of_work(metadata=None, timeout=None):
    start = time.time()

    def decorator(func):
        def wrapper(*args, **kwargs):
            try:
                result = func(*args, **kwargs)
                elapsed = time.time() - start
                if elapsed > timeout:
                    raise TimeoutError("Transaction timed out")
                if metadata:
                    args[0].metadata(metadata)
                return result
            except Exception as e:
                if metadata:
                    args[0].metadata({'error': str(e)})
                raise
        return wrapper
    return decorator

