def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    observer_schemas = {}
    for manifest in app.spec.manifest:
        if manifest.spec.observing and manifest.spec.observing.type == "MONITORING":
            observed_resource = manifest.spec.observed.type
            if observed_resource not in observer_schemas:
                observer_schemas[observed_resource] = {
                    ".kind": observed_resource,
                    "title": f"Observer Schema for {observed_resource}",
                    "type": "object",
                    "properties": {}
                }
    return observer_schemas

