def _extract_number_and_supplement_from_issue_element(issue):
    def _extract_value(value):
        value = value.replace('sp.', 'spe').replace('.', '')
        for key in ['spe', 'spe.']:
            if key in value:
                return key
        return 'suppl'

    matches = re.findall(r'(\d+)\s*(suppl|spe|s2|spe.1|spe2|spe.2|spepr|supp|supp.1|supp5|suppl.12|suppl.1-2)', issue)
    if not matches:
        return None, None

    number = int(matches[0][0])
    supplement = _extract_value(matches[0][1])
    return number, supplement

