def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""

    if not isinstance(obj, dict):
        raise TypeError(f"Input must be a dictionary, but got {type(obj)}")

    def _recurse(dumper, data):
        if isinstance(data, dict):
            return dumper.represent_mapping(data)
        elif isinstance(data, list):
            return dumper.represent_sequence(data)
        elif isinstance(data, str):
            return dumper.represent_scalar('str', data)
        elif isinstance(data, (int, float, bool)):
            return dumper.represent_scalar('tag:yaml.org,2002:', repr(data))
        elif data is None:
            return dumper.represent_scalar('tag:yaml.org,2002:null')
        elif callable(data):
            data.__name__ = 'function'
        return None  # No Python object found

    return dumper.represent_mapping(obj)

